import React from 'react';
import { BrowserRouter, Routes, Route, useLocation } from 'react-router-dom';
import LoginPage from './Pages/LogInPage';
import Homepage from './Pages/Homepage/Homepage';
import Navbar from './Components/NavBar/navbar';
import FacultatiPage from './Pages/FacultatiPage/FacultatiPage';
import Header from './Components/Header/Header';
import CalendarPage from './Pages/Calendar/CalendarPage';
import TestPage from './Pages/TestPage/TestPage';
import './App.css';

function App() {
  const NavbarWithVisibility = () => {
    const location = useLocation();
    const hideNavbarPaths = ["/", "/login"];
    return hideNavbarPaths.includes(location.pathname) ? null : <Navbar />;
  };
  const HeaderWithVisibility = () => {
    const location = useLocation();
    const hideNavbarPaths = ["/", "/login"];
    return hideNavbarPaths.includes(location.pathname) ? null : <Header/>;
  };

  return (
    <BrowserRouter>
      <div className="App">
        <HeaderWithVisibility/>
        
        <NavbarWithVisibility />
        
        <Routes>
          <Route path="/" element={<LoginPage />} />
          <Route path="/login" element={<LoginPage />} />
          <Route path="/homepage" element={<Homepage />} />
          <Route path="/facultati" element={<FacultatiPage />} />
          <Route path="/calendar" element={<CalendarPage/>}/>
          <Route path="/test" element={<TestPage/>}/>
        </Routes>
      </div>
    </BrowserRouter>
  );
}

export default App;
