import React, {useState, useEffect} from 'react';
import {
  MenuItem,
  Typography,
  Box,
  Button,
  Menu,
} from '@mui/material';
import ArrowDropDownIcon from '@mui/icons-material/ArrowDropDown';
import { useNavigate } from 'react-router-dom'; // For navigation
import axios from "axios";
//import API_BASE_URL from "api";

const API_BASE_URL = "https://localhost:7140/api";

const FacultatiPage: React.FC = () => {
  const [selectedOption, setSelectedOption] = React.useState("");
  const [selectedGrupa, setSelectedGrupa] = React.useState("");
  const [selectedMaterie, setSelectedMaterie] = React.useState("");
  const [anchorEl, setAnchorEl] = React.useState<null | HTMLElement>(null);
  const [grupaAnchorEl, setGrupaAnchorEl] = React.useState<null | HTMLElement>(null);
  const [materieAnchorEl, setMaterieAnchorEl] = React.useState<null | HTMLElement>(null);

  const navigate = useNavigate(); // Hook to navigate between pages

  const MyPage = () => {
    const [data, setData] = useState(null); // State to store fetched data
    const [loading, setLoading] = useState(true); // Loading state
    const [error, setError] = useState(null); // Error state

    useEffect(() => {
        // Function to fetch data
        const fetchData = async () => {
            try {
                setLoading(true); // Start loading
                const response = await axios.get(`${API_BASE_URL}/facultate`); // Replace with your API URL
                console.log(response.data);
                setData(response.data); // Update state with fetched data
            } catch (err) {
                //setError(err.message); // Handle errors
            } finally {
                setLoading(false); // End loading
            }
        };

        fetchData(); // Call the fetch function
    }, []); // Empty dependency array ensures this runs only on component mount (page load)

    if (loading) return <p>Loading...</p>; // Show loading message
    if (error) return <p>Error: {error}</p>; // Show error message

    return (
        <div>
            <h1>Data from API</h1>
            <pre>{JSON.stringify(data, null, 2)}</pre> {/* Display fetched data */}
        </div>
    );
};

  // Facultati Dropdown functions
  const handleDropdownClick = (event: React.MouseEvent<HTMLButtonElement>) => {
    setAnchorEl(event.currentTarget);
  };

  const handleClose = () => {
    setAnchorEl(null);
    setGrupaAnchorEl(null);
    setMaterieAnchorEl(null);
  };

  const handleSelect = (option: string) => {
    setSelectedOption(option);
    handleClose();
  };

  // Grupa Dropdown functions
  const handleGrupaClick = (event: React.MouseEvent<HTMLButtonElement>) => {
    setGrupaAnchorEl(event.currentTarget);
  };

  const handleGrupaSelect = (grupa: string) => {
    setSelectedGrupa(grupa);
    handleClose();
  };

  // Materie Dropdown functions
  const handleMaterieClick = (event: React.MouseEvent<HTMLButtonElement>) => {
    setMaterieAnchorEl(event.currentTarget);
  };

  const handleMaterieSelect = (materie: string) => {
    setSelectedMaterie(materie);
    handleClose();
  };

  const handleGoToCalendar = () => {
    navigate('/calendar'); // Change '/calendar' to the route of your calendar page
  };

  const facultyOptions = [
    "Facultatea de inginerie electrica si stiinta calculatoarelor",
    "Facultatea de Litere și Științe ale Comunicării",
    "Facultatea de Drept și Științe Administrative",
    "Facultatea de Medicină și Științe Biologice",
    "Facultatea de Economie ,Administrație și Afaceri",
  ];

  const grupaOptions = ["1", "2", "3"];
  const materieOptions = ["Matematica", "Fizica", "Informatica", "Chimie"];

  return (
    <Box
      sx={{
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        height: '100vh',
        bgcolor: '#f0f0f0',
      }}
    >
      <Box
        sx={{
          width: '300px',
          bgcolor: '#003D7B',
          color: 'white',
          borderRadius: '8px',
          padding: '16px',
          boxShadow: '0px 2px 4px rgba(0, 0, 0, 0.1)',
          textAlign: 'center',
        }}
      >
        <Typography
          variant="h6"
          sx={{
            marginBottom: '16px',
            fontWeight: 'bold',
          }}
        >
          Facultati
        </Typography>

        <Button
          variant="contained"
          onClick={handleDropdownClick}
          sx={{
            bgcolor: '#003D7B',
            color: 'white',
            '&:hover': { bgcolor: '#0056a6' },
            width: '100%',
            marginBottom: '16px',
          }}
        >
          {selectedOption || 'Select an option'}
        </Button>

        <Menu
          anchorEl={anchorEl}
          open={Boolean(anchorEl)}
          onClose={handleClose}
          MenuListProps={{
            sx: {
              bgcolor: '#003D7B',
              color: 'white',
            },
          }}
        >
          {facultyOptions.map((option, index) => (
            <MenuItem
              key={index}
              onClick={() => handleSelect(option)}
              sx={{
                bgcolor: '#003D7B',
                color: 'white',
                '&:hover': { bgcolor: '#0056a6' },
              }}
            >
              {option}
            </MenuItem>
          ))}
        </Menu>

        <Typography
          variant="h6"
          sx={{
            marginBottom: '16px',
            fontWeight: 'bold',
          }}
        >
          Grupa
        </Typography>

        <Button
          variant="contained"
          onClick={handleGrupaClick}
          sx={{
            bgcolor: '#003D7B',
            color: 'white',
            '&:hover': { bgcolor: '#0056a6' },
            width: '100%',
            marginBottom: '16px',
          }}
        >
          {selectedGrupa || 'Select a Grupa'}
        </Button>

        <Menu
          anchorEl={grupaAnchorEl}
          open={Boolean(grupaAnchorEl)}
          onClose={handleClose}
          MenuListProps={{
            sx: {
              bgcolor: '#003D7B',
              color: 'white',
            },
          }}
        >
          {grupaOptions.map((grupa, index) => (
            <MenuItem
              key={index}
              onClick={() => handleGrupaSelect(grupa)}
              sx={{
                bgcolor: '#003D7B',
                color: 'white',
                '&:hover': { bgcolor: '#0056a6' },
              }}
            >
              {grupa}
            </MenuItem>
          ))}
        </Menu>

        <Typography
          variant="h6"
          sx={{
            marginBottom: '16px',
            fontWeight: 'bold',
          }}
        >
          Materie
        </Typography>

        <Button
          variant="contained"
          onClick={handleMaterieClick}
          sx={{
            bgcolor: '#003D7B',
            color: 'white',
            '&:hover': { bgcolor: '#0056a6' },
            width: '100%',
            marginBottom: '16px',
          }}
        >
          {selectedMaterie || 'Select a Materie'}
        </Button>

        <Menu
          anchorEl={materieAnchorEl}
          open={Boolean(materieAnchorEl)}
          onClose={handleClose}
          MenuListProps={{
            sx: {
              bgcolor: '#003D7B',
              color: 'white',
            },
          }}
        >
          {materieOptions.map((materie, index) => (
            <MenuItem
              key={index}
              onClick={() => handleMaterieSelect(materie)}
              sx={{
                bgcolor: '#003D7B',
                color: 'white',
                '&:hover': { bgcolor: '#0056a6' },
              }}
            >
              {materie}
            </MenuItem>
          ))}
        </Menu>

        {/* Add Go to Calendar button */}
        <Button
          variant="contained"
          onClick={handleGoToCalendar}
          sx={{
            bgcolor: '#0056a6',
            color: 'white',
            '&:hover': { bgcolor: '#007bff' },
            width: '100%',
            marginTop: '16px', // Add spacing above the button
          }}
        >
          Go to Calendar
        </Button>
      </Box>
    </Box>
  );
};

export default FacultatiPage;
